xml.Script:
        include 'Figures\Scripts\Cube_Standard_Colors.inc';

        //            up face left right back bottom
        Labels[0] := 'yog bbb ggo www obr wyg';
        Labels[1] := 'orr obb oyw wwb ygy goy';
        Labels[2] := 'yrr gry rwr ogw ogy brb';

        W := 0.5;
        N := 3;
        D := 2 * W / N;

        DX := -0.03;
        DY := -0.08;
        DZ := -0.15;

        function GetColor(Offset, X, Y);
        begin
          Result := -1;
          C := copy(Labels[Y], Offset * (N + 1) + X + 1, 1);
          if      C = 'r' then Result := clRed
          else if C = 'o' then Result := clOrange
          else if C = 'g' then Result := clGreen
          else if C = 'b' then Result := clBlue
          else if C = 'y' then Result := clYellow
          else if C = 'w' then Result := clWhite;
        end;

